A \textbf{rational function} has the form:
\[
\frac{P(x)}{Q(x)}
\]

where $P(x)$ and $Q(x)$ are polynomials.

\textbf{Proper vs. Improper:}
\begin{itemize}
    \item \textbf{Proper:} $\deg(P) < \deg(Q)$ -- can use partial fractions directly
    \item \textbf{Improper:} $\deg(P) \geq \deg(Q)$ -- first perform polynomial long division
\end{itemize}

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Basic Idea:}}

Break down a complicated fraction:
\[
\frac{2x+1}{(x-1)(x+3)} = \frac{A}{x-1} + \frac{B}{x+3}
\]

into simpler fractions that are easy to integrate.

\vspace{0.5cm}

\textbf{Case 1: Distinct Linear Factors}

If $Q(x) = (x-a_1)(x-a_2)\cdots(x-a_n)$ with all $a_i$ distinct:
\[
\frac{P(x)}{Q(x)} = \frac{A_1}{x-a_1} + \frac{A_2}{x-a_2} + \cdots + \frac{A_n}{x-a_n}
\]

\vspace{0.3cm}
\textbf{Case 2: Repeated Linear Factors}

If $Q(x)$ contains $(x-a)^k$:
\[
\frac{P(x)}{Q(x)} = \frac{A_1}{x-a} + \frac{A_2}{(x-a)^2} + \cdots + \frac{A_k}{(x-a)^k} + \text{(other terms)}
\]

\vspace{0.3cm}
\textbf{Case 3: Distinct Irreducible Quadratic Factors}

If $Q(x)$ contains $ax^2 + bx + c$ (which cannot be factored):
\[
\frac{P(x)}{Q(x)} = \frac{Ax + B}{ax^2 + bx + c} + \text{(other terms)}
\]

\vspace{0.3cm}
\textbf{Case 4: Repeated Irreducible Quadratic Factors}

If $Q(x)$ contains $(ax^2 + bx + c)^k$:
\[
\frac{P(x)}{Q(x)} = \frac{A_1x + B_1}{ax^2+bx+c} + \frac{A_2x + B_2}{(ax^2+bx+c)^2} + \cdots + \text{(other terms)}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Strategy:}}
\begin{enumerate}
    \item Factor the denominator completely
    \item Set up partial fraction form based on factors
    \item Multiply both sides by denominator
    \item Solve for unknown constants
    \item Integrate each term separately
\end{enumerate}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate $\displaystyle \int \frac{5x-2}{x^2-x-2} \, dx$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Factor denominator

\begin{align*}
x^2 - x - 2 &= (x-2)(x+1)
\end{align*}

\textbf{Step 2:} Set up partial fractions

\[
\frac{5x-2}{(x-2)(x+1)} = \frac{A}{x-2} + \frac{B}{x+1}
\]

\textbf{Step 3:} Multiply by $(x-2)(x+1)$

\begin{align*}
5x - 2 &= A(x+1) + B(x-2)
\end{align*}

\textbf{Step 4:} Solve for $A$ and $B$

\textbf{Method 1: Substitution}

Let $x = 2$: $5(2)-2 = A(3) + 0 \implies 8 = 3A \implies A = \frac{8}{3}$

Let $x = -1$: $5(-1)-2 = 0 + B(-3) \implies -7 = -3B \implies B = \frac{7}{3}$

\textbf{Method 2: Compare coefficients}

$5x - 2 = Ax + A + Bx - 2B = (A+B)x + (A-2B)$

Coefficients of $x$: $5 = A + B$

Constants: $-2 = A - 2B$

Solving: $A = \frac{8}{3}$, $B = \frac{7}{3}$

\textbf{Step 5:} Integrate

\begin{align*}
\int \frac{5x-2}{x^2-x-2} \, dx &= \int \left(\frac{8/3}{x-2} + \frac{7/3}{x+1}\right) dx \\
&= \frac{8}{3}\int \frac{1}{x-2} \, dx + \frac{7}{3}\int \frac{1}{x+1} \, dx \\
&= \frac{8}{3}\ln|x-2| + \frac{7}{3}\ln|x+1| + C
\end{align*}

\textbf{Answer:} \boxed{\frac{8}{3}\ln|x-2| + \frac{7}{3}\ln|x+1| + C}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate $\displaystyle \int \frac{2x}{(x-1)^2(x+2)} \, dx$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Set up partial fractions (repeated factor $(x-1)^2$)

\[
\frac{2x}{(x-1)^2(x+2)} = \frac{A}{x-1} + \frac{B}{(x-1)^2} + \frac{C}{x+2}
\]

\textbf{Step 2:} Multiply by $(x-1)^2(x+2)$

\begin{align*}
2x &= A(x-1)(x+2) + B(x+2) + C(x-1)^2
\end{align*}

\textbf{Step 3:} Solve for constants

Let $x = 1$: $2 = 0 + B(3) + 0 \implies B = \frac{2}{3}$

Let $x = -2$: $-4 = 0 + 0 + C(9) \implies C = -\frac{4}{9}$

Let $x = 0$: $0 = A(-1)(2) + \frac{2}{3}(2) + (-\frac{4}{9})(1)$

$0 = -2A + \frac{4}{3} - \frac{4}{9}$

$0 = -2A + \frac{12-4}{9} = -2A + \frac{8}{9}$

$A = \frac{4}{9}$

\textbf{Step 4:} Integrate

\begin{align*}
\int \frac{2x}{(x-1)^2(x+2)} \, dx &= \int \left(\frac{4/9}{x-1} + \frac{2/3}{(x-1)^2} + \frac{-4/9}{x+2}\right) dx \\
&= \frac{4}{9}\ln|x-1| + \frac{2}{3} \cdot \frac{-1}{x-1} - \frac{4}{9}\ln|x+2| + C \\
&= \frac{4}{9}\ln|x-1| - \frac{2}{3(x-1)} - \frac{4}{9}\ln|x+2| + C
\end{align*}

\textbf{Answer:} \boxed{\frac{4}{9}\ln\left|\frac{x-1}{x+2}\right| - \frac{2}{3(x-1)} + C}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate $\displaystyle \int \frac{x^2 + 2x + 3}{(x+1)(x^2+1)} \, dx$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Set up partial fractions ($x^2+1$ is irreducible)

\[
\frac{x^2+2x+3}{(x+1)(x^2+1)} = \frac{A}{x+1} + \frac{Bx+C}{x^2+1}
\]

\textbf{Step 2:} Multiply by $(x+1)(x^2+1)$

\begin{align*}
x^2 + 2x + 3 &= A(x^2+1) + (Bx+C)(x+1)
\end{align*}

\textbf{Step 3:} Solve for constants

Let $x = -1$: $1 - 2 + 3 = A(2) + 0 \implies 2 = 2A \implies A = 1$

Expand right side:
\begin{align*}
x^2 + 2x + 3 &= Ax^2 + A + Bx^2 + Bx + Cx + C \\
&= (A+B)x^2 + (B+C)x + (A+C)
\end{align*}

Comparing coefficients:
\begin{align*}
x^2: \quad & 1 = A + B \implies B = 0 \\
x^1: \quad & 2 = B + C \implies C = 2 \\
x^0: \quad & 3 = A + C \implies 3 = 1 + 2 \quad \checkmark
\end{align*}

So: $A = 1$, $B = 0$, $C = 2$

\textbf{Step 4:} Integrate

\begin{align*}
\int \frac{x^2+2x+3}{(x+1)(x^2+1)} \, dx &= \int \left(\frac{1}{x+1} + \frac{2}{x^2+1}\right) dx \\
&= \ln|x+1| + 2\arctan x + C
\end{align*}

\textbf{Answer:} \boxed{\ln|x+1| + 2\arctan x + C}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Note:}} Remember $\int \dfrac{1}{x^2+1} \, dx = \arctan x + C$

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 5.6 Summary: Partial Fractions}}

\textbf{Procedure:}
\begin{enumerate}
    \item Check if proper; if not, do long division first
    \item Factor denominator completely
    \item Set up partial fraction form based on factor types
    \item Multiply both sides by common denominator
    \item Solve for constants (substitution or compare coefficients)
    \item Integrate each term separately
\end{enumerate}

\textbf{Partial Fraction Forms:}

\begin{center}
\begin{tabular}{|p{5cm}|p{5.5cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Factor Type} & \textbf{Partial Fraction} \\
\hline
$(x-a)$ distinct & $\dfrac{A}{x-a}$ \\
\hline
$(x-a)^k$ repeated & $\dfrac{A_1}{x-a} + \dfrac{A_2}{(x-a)^2} + \cdots + \dfrac{A_k}{(x-a)^k}$ \\
\hline
$ax^2+bx+c$ irreducible & $\dfrac{Ax+B}{ax^2+bx+c}$ \\
\hline
\end{tabular}
\end{center}

\textbf{Common Integrals from Partial Fractions:}
\begin{align*}
\int \frac{1}{x-a} \, dx &= \ln|x-a| + C \\
\int \frac{1}{(x-a)^n} \, dx &= \frac{-1}{(n-1)(x-a)^{n-1}} + C \quad (n \neq 1) \\
\int \frac{1}{x^2+1} \, dx &= \arctan x + C \\
\int \frac{1}{x^2+a^2} \, dx &= \frac{1}{a}\arctan\left(\frac{x}{a}\right) + C
\end{align*}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Forgetting to do long division for improper fractions
    \item Wrong partial fraction form for repeated factors
    \item Using $\frac{A}{ax^2+bx+c}$ instead of $\frac{Ax+B}{ax^2+bx+c}$ for quadratics
    \item Arithmetic errors when solving for constants
    \item Forgetting absolute value in logarithms
\end{itemize}

\textcolor{green}{\textbf{Pro Tip:}} Always verify your partial fraction decomposition by combining fractions back together!

