\vspace{0.2cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the area of the region bounded by $y = x^2$ and $y = 2x + 3$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find intersection points

Set $x^2 = 2x + 3$:
\begin{align*}
x^2 - 2x - 3 &= 0 \\
(x - 3)(x + 1) &= 0 \\
x &= -1 \text{ or } x = 3
\end{align*}

\textbf{Step 2:} Determine which is on top

Test a point between $-1$ and $3$, say $x = 0$:
\begin{itemize}
    \item $y = x^2 = 0$
    \item $y = 2x + 3 = 3$
\end{itemize}

So $2x + 3 > x^2$ on $[-1, 3]$.

\textbf{Step 3:} Set up integral

\[
A = \int_{-1}^3 [(2x + 3) - x^2] \, dx
\]

\textbf{Step 4:} Evaluate

\begin{align*}
A &= \int_{-1}^3 (2x + 3 - x^2) \, dx \\
&= \left[x^2 + 3x - \frac{x^3}{3}\right]_{-1}^3 \\
&= \left[9 + 9 - 9\right] - \left[1 - 3 + \frac{1}{3}\right] \\
&= 9 - \left(-2 + \frac{1}{3}\right) \\
&= 9 + 2 - \frac{1}{3} \\
&= 11 - \frac{1}{3} \\
&= \frac{32}{3}
\end{align*}

\textbf{Answer:} \boxed{A = \frac{32}{3} \text{ square units}}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the area enclosed by $y = \sin x$ and $y = \cos x$ from $x = 0$ to their first intersection point.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find intersection

\begin{align*}
\sin x &= \cos x \\
\tan x &= 1 \\
x &= \frac{\pi}{4} \quad \text{(first intersection)}
\end{align*}

\textbf{Step 2:} Determine which is on top on $[0, \pi/4]$

At $x = 0$: $\cos 0 = 1 > \sin 0 = 0$

So $\cos x > \sin x$ on $[0, \pi/4]$.

\textbf{Step 3:} Set up and evaluate

\begin{align*}
A &= \int_0^{\pi/4} (\cos x - \sin x) \, dx \\
&= [\sin x + \cos x]_0^{\pi/4} \\
&= \left[\sin\frac{\pi}{4} + \cos\frac{\pi}{4}\right] - [\sin 0 + \cos 0] \\
&= \left[\frac{\sqrt{2}}{2} + \frac{\sqrt{2}}{2}\right] - [0 + 1] \\
&= \sqrt{2} - 1
\end{align*}

\textbf{Answer:} \boxed{A = \sqrt{2} - 1 \text{ square units}}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the area of the region bounded by $y = x^2 - 4$ and the $x$-axis from $x = -2$ to $x = 2$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Observe that $x^2 - 4 \leq 0$ on $[-2, 2]$

The curve is below the $x$-axis.

\textbf{Step 2:} For actual area, use $|f(x)|$ or $-f(x)$

\begin{align*}
A &= \int_{-2}^2 |x^2 - 4| \, dx \\
&= \int_{-2}^2 -(x^2 - 4) \, dx \\
&= \int_{-2}^2 (4 - x^2) \, dx
\end{align*}

\textbf{Step 3:} Evaluate

\begin{align*}
A &= \left[4x - \frac{x^3}{3}\right]_{-2}^2 \\
&= \left[8 - \frac{8}{3}\right] - \left[-8 + \frac{8}{3}\right] \\
&= 8 - \frac{8}{3} + 8 - \frac{8}{3} \\
&= 16 - \frac{16}{3} \\
&= \frac{32}{3}
\end{align*}

\textbf{Answer:} \boxed{A = \frac{32}{3} \text{ square units}}

\textcolor{green}{\textbf{Note:}} If we had computed $\int_{-2}^2 (x^2 - 4) \, dx$, we'd get $-\frac{32}{3}$ (negative because curve is below axis). The area is always positive!

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 5.10 Summary: Area Applications}}

\textbf{Area Under a Curve:}

If $f(x) \geq 0$ on $[a, b]$:
\[
\boxed{A = \int_a^b f(x) \, dx}
\]

If $f(x) \leq 0$ on $[a, b]$:
\[
\boxed{A = -\int_a^b f(x) \, dx = \int_a^b |f(x)| \, dx}
\]

\textbf{Area Between Two Curves:}

If $f(x) \geq g(x)$ on $[a, b]$:
\[
\boxed{A = \int_a^b [f(x) - g(x)] \, dx = \int_a^b [\text{top} - \text{bottom}] \, dx}
\]

\textbf{Step-by-Step Procedure:}
\begin{enumerate}
    \item Sketch both curves
    \item Find intersection points (set equal and solve)
    \item Determine which curve is on top
    \item Set up integral with (top $-$ bottom)
    \item Evaluate using FTC
\end{enumerate}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Subtracting in wrong order (bottom $-$ top gives negative!)
    \item Forgetting to find intersection points
    \item Not checking which curve is on top
    \item Confusing definite integral value (can be negative) with area (always positive)
\end{itemize}

\textcolor{red}{\textbf{Exam Alert:}} Area between curves appears frequently in exams. Always sketch the region first!

\textcolor{green}{\textbf{Pro Tip:}} When in doubt, sketch! A quick graph makes it clear which function is on top.

